import{_ as o,o as i,c as a,a2 as d}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Verifica manuale di M22: nomi dei file senza estensione e applicazioni su Windows e Linux","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m22-nomi-file-e-applicazioni.md","filePath":"qa/m22-nomi-file-e-applicazioni.md"}'),t={name:"qa/m22-nomi-file-e-applicazioni.md"};function n(c,e,s,r,l,p){return i(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="verifica-manuale-di-m22-nomi-dei-file-senza-estensione-e-applicazioni-su-windows-e-linux" tabindex="-1">Verifica manuale di M22: nomi dei file senza estensione e applicazioni su Windows e Linux <a class="header-anchor" href="#verifica-manuale-di-m22-nomi-dei-file-senza-estensione-e-applicazioni-su-windows-e-linux" aria-label="Permalink to &quot;Verifica manuale di M22: nomi dei file senza estensione e applicazioni su Windows e Linux&quot;">​</a></h1><p>Prove a mano per ciò che le suite automatiche non vedono: l&#39;esploratore su un vault vero e, per le applicazioni, la finestra reale di Windows e di Linux. Il lavoro è descritto in <a href="./../roadmap.html#13-quindecies-m22--applicazioni-integrate-su-windows-e-linux-nomi-dei-file-senza-estensione">roadmap §13-quindecies</a> e negli ADR <a href="./../adr/0062-vista-integrata-windows-linux.html">0062</a> e <a href="./../adr/0063-nomi-file-senza-estensione.html">0063</a>, <strong>entrambi accettati il 2026-11-20</strong> (recepiti in <code>Specifications.md</code> v1.8 il 2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> resta come storia).</p><p><strong>Stato al 2026-11-19: nessun caso di questo runbook è stato eseguito.</strong> I nomi e i comandi sono stati letti sul codice e su <code>Taskfile.yml</code>. La colonna «Esito» è vuota di proposito: si scrive <code>ok</code>, <code>ko</code> (con una riga sul difetto e il livello P0, P1 o P2) oppure <code>n/d</code>, con data, sistema e versione, nel registro in fondo.</p><h2 id="che-cosa-coprono-gia-le-prove-automatiche" tabindex="-1">Che cosa coprono già le prove automatiche <a class="header-anchor" href="#che-cosa-coprono-gia-le-prove-automatiche" aria-label="Permalink to &quot;Che cosa coprono già le prove automatiche&quot;">​</a></h2><p><strong>Coperto (non va ripetuto a mano, salvo dubbio):</strong></p><ul><li><strong>Nomi senza estensione (N1…N9).</strong> vitest: <code>embeds/media.test.ts</code> (<code>splitName</code>, <code>displayName</code>, <code>displayPath</code>: <code>.md</code>, <code>.MD</code>, <code>.excalidraw.md</code>, <code>.png</code>, <code>.docx</code>, <code>LICENSE</code>, <code>.gitignore</code>, <code>a.b.canvas</code>), <code>app/rename.test.ts</code> (<code>renameTarget</code> e <code>promptRename</code>), <code>sidebar/FileExplorer.webapp.test.tsx</code>, <code>sidebar/trees.test.ts</code>, <code>workspace/TabBar.test.tsx</code>, <code>bookmarks/model.test.ts</code>, <code>embeds/hydrate.test.ts</code>, <code>webapp/model.test.ts</code>, <code>canvas/preview.test.ts</code>. E2E sul mock dei binding e sul core WASM (<code>task e2e</code>, <code>yarn workspace @clarae/web run e2e:workbench-ui</code>): in <code>apps/desktop/frontend/e2e/</code>, <code>keyboard.spec.ts</code> («F2 shows a file without its extension and the rename keeps it»), <code>workflows.spec.ts</code>, <code>drawing.spec.ts</code>, <code>drawing-wp5.spec.ts</code>, <code>drawing-embed.spec.ts</code>, <code>marp-show-layout.spec.ts</code>, <code>marp.spec.ts</code>, <code>open-by-type.spec.ts</code> e <code>cloud.ts</code>.</li><li><strong>Ripiego delle applicazioni.</strong> <code>internal/webview/manager_test.go</code> (<code>TestAPlatformThatCannotShowViewsIsUnavailableForTheSession</code>, <code>TestAPlatformFailureAfterAViewWasMadeDoesNotEndTheSession</code>, <code>TestAnOrdinaryCreateFailureKeepsTheManagerAvailable</code>), <code>internal/app/bindings_webview_test.go</code> (<code>TestAPlatformThatCannotShowViewsFallsBackToTheSystemBrowser</code>), <code>internal/shell/nativeview/switch_test.go</code> (<code>CLARAE_WEBVIEW</code>), <code>datafolders_test.go</code>, <code>driver_windows_test.go</code>, <code>internal/app/capabilities_test.go</code>.</li><li><strong>Compilazione dei due driver.</strong> <code>task vet-windows</code> e <code>task vet-linux</code> (in <code>task ci</code>).</li><li><strong>Driver Linux contro una finestra vera di Wails sotto Xvfb (X11).</strong> <code>task test-nativeview-linux</code>, a mano e in Docker, con la sandbox di WebKit accesa: 14 test (su un Mac arm64 serve <code>LINUX_ARCH=arm64</code>). Vedi la matrice.</li></ul><p><strong>Non coperto (è lo scopo di questo runbook):</strong> l&#39;esploratore sul vault reale dell&#39;owner; i driver di Windows e di Linux su una finestra vera (X11, Wayland, GPU reale, input veri); il ripiego su una macchina che il runtime non ce l&#39;ha.</p><h2 id="_0-preparazione" tabindex="-1">0. Preparazione <a class="header-anchor" href="#_0-preparazione" aria-label="Permalink to &quot;0. Preparazione&quot;">​</a></h2><ul><li>Un build del client del 2026-11-19 o successivo (la sezione <em>Unreleased</em> del <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>): <code>task run-desktop</code> per macOS con il vault demo, oppure il pacchetto per Windows o Linux.</li><li>Per i nomi (sezione 1): un vault con file di tutti i tipi. Il vault dell&#39;owner, con <code>Desktop_UI</code>, <code>SlideClarae</code> e <code>SATAP</code>, va bene; altrimenti creare a mano nella stessa cartella <code>Piano.md</code>, <code>Piano.canvas</code>, <code>Schema.excalidraw</code>, <code>Review.marp</code>, <code>Sito.webapp</code>, <code>Tabella.base</code>, <code>foto.png</code>, <code>manuale.pdf</code>, <code>documento.docx</code>, <code>LICENSE</code>, <code>.gitignore</code>, <code>Lettere/</code> (una cartella) e <code>Vecchio.excalidraw.md</code> (un disegno nel formato del plugin Obsidian).</li><li>Per le applicazioni (sezione 2): la matrice <a href="./m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>, sezioni 2 (Windows) e 3 (Linux), con la preparazione che descrive.</li></ul><h2 id="_1-nomi-dei-file-senza-estensione-macos-windows-linux-workbench-web" tabindex="-1">1. Nomi dei file senza estensione (macOS, Windows, Linux, workbench web) <a class="header-anchor" href="#_1-nomi-dei-file-senza-estensione-macos-windows-linux-workbench-web" aria-label="Permalink to &quot;1. Nomi dei file senza estensione (macOS, Windows, Linux, workbench web)&quot;">​</a></h2><p>La stessa interfaccia gira su desktop e su workbench web: eseguire su almeno un desktop e, per N1, N2 e N7, anche sul workbench web.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>N1</td><td>Esploratore: file supportati</td><td>Aprire il vault della preparazione e guardare l&#39;albero.</td><td><code>Piano</code>, <code>Piano</code>, <code>Schema</code>, <code>Review</code>, <code>Sito</code>, <code>Tabella</code>, <code>foto</code>, <code>manuale</code>, <code>Vecchio</code> senza estensione (le due <code>Piano</code> sono una accanto all&#39;altra e si distinguono dall&#39;icona); il suggerimento di ogni riga mostra il <strong>percorso con l&#39;estensione</strong>. Nel vault dell&#39;owner: <code>Desktop_UI</code>, <code>SlideClarae</code>, <code>SATAP</code>.</td><td></td></tr><tr><td>N2</td><td>Esploratore: file non supportati</td><td>Guardare <code>documento.docx</code>, <code>LICENSE</code>, <code>.gitignore</code> e la cartella <code>Lettere</code>.</td><td><code>documento.docx</code>, <code>LICENSE</code> e <code>.gitignore</code> con il <strong>nome intero</strong>; la cartella com&#39;è. Un clic su <code>documento.docx</code> lo apre con il programma del sistema.</td><td></td></tr><tr><td>N3</td><td>Schede e intestazioni</td><td>Aprire una nota, un disegno, una lavagna, una base e un&#39;applicazione.</td><td>La scheda mostra il nome senza estensione. L&#39;intestazione della vista mostra <strong>cartella e nome</strong> senza estensione (<code>Cartella/Piano</code>), per note, disegni e lavagne.</td><td></td></tr><tr><td>N4</td><td>Rinomina con F2: disegno</td><td>Selezionare <code>Schema</code> nell&#39;albero, <code>F2</code>: il campo deve contenere <code>Schema</code>. Scrivere <code>Diagramma</code> e <code>Invio</code>.</td><td>Il campo <strong>non</strong> mostra <code>.excalidraw</code>. Dopo <code>Invio</code> il file sul disco è <code>Diagramma.excalidraw</code> (controllare nel Finder, in Esplora risorse o con <code>ls</code>) e si apre ancora come disegno.</td><td></td></tr><tr><td>N5</td><td>Rinomina: estensione digitata</td><td><code>F2</code> su <code>Diagramma</code>, scrivere <code>Altro.excalidraw</code>, <code>Invio</code>. Poi <code>F2</code> su una nota e scrivere <code>Foo.txt</code>.</td><td>Il primo diventa <code>Altro.excalidraw</code> (<strong>non</strong> <code>Altro.excalidraw.excalidraw</code>). La nota diventa <code>Foo.txt.md</code>: un&#39;altra estensione digitata resta parte del nome.</td><td></td></tr><tr><td>N6</td><td>Rinomina: casi limite</td><td><code>F2</code> e <code>Invio</code> senza cambiare nulla; <code>F2</code> e un nome vuoto o di soli spazi; <code>F2</code> e un nome con spazi ai lati (<code> Piano due </code>); <code>Esc</code>.</td><td>Nessuna azione per nome uguale, vuoto o <code>Esc</code>; gli spazi ai lati si tolgono (<code>Piano due</code>).</td><td></td></tr><tr><td>N7</td><td>Rinomina: gli altri punti d&#39;ingresso</td><td>Menu contestuale della riga → <em>Rinomina</em> su una lavagna; comando <em>Rinomina nota</em> dalla palette (scorciatoia <code>F2</code>) sulla nota attiva e su una presentazione <code>.marp</code>.</td><td>Stesso comportamento di N4: il campo senza estensione e l&#39;estensione conservata. Le conferme di aggiornamento dei link compaiono come prima.</td><td></td></tr><tr><td>N8</td><td>Rinomina: non supportati e cartelle</td><td><code>F2</code> su <code>documento.docx</code> e su <code>Lettere</code>.</td><td>Il campo contiene il <strong>nome intero</strong> (<code>documento.docx</code>); la rinomina usa ciò che si scrive, com&#39;era.</td><td></td></tr><tr><td>N9</td><td>Legacy <code>X.excalidraw.md</code></td><td>Guardare <code>Vecchio.excalidraw.md</code> nell&#39;albero; <code>F2</code>.</td><td>Compare come <code>Vecchio</code>; <code>F2</code> mostra <code>Vecchio</code> e conserva <code>.excalidraw.md</code>.</td><td></td></tr><tr><td>N10</td><td>Link, segnalibri e conferme</td><td>Rinominare una nota su cui puntano altre note e un segnalibro; mettere nel cestino un disegno e una cartella; creare un link con <code>[[</code> verso una presentazione <code>.marp</code>.</td><td>I link e i segnalibri si aggiornano. La conferma del cestino mostra il percorso <strong>senza estensione</strong> per il file e intero per la cartella. Il link a una presentazione inserisce <strong><code>Review.marp</code></strong> (con estensione: i link si risolvono per estensione).</td><td></td></tr><tr><td>N11</td><td>Pannelli e selettori</td><td>Pannello <em>Link</em>: nota con collegamenti inversi da un disegno e da una lavagna; palette <em>Apri applicazione…</em>; selettore delle immagini nei disegni; finestra di recupero e cronologia di una nota.</td><td>Nei pannelli e negli elenchi i nomi sono senza estensione; un file non supportato che compare in un elenco con il nome intero. Nel selettore delle immagini dei disegni <strong>non</strong> compare l&#39;estensione.</td><td></td></tr><tr><td>N12</td><td>Selettore rapido e ricerca</td><td><code>Mod+O</code> e la ricerca con il nome di un disegno e di un&#39;applicazione.</td><td>Come prima: nessuna estensione (viene dal titolo dell&#39;indice). Nessuna regressione.</td><td></td></tr><tr><td>N13</td><td>Selettori con etichette uguali</td><td>In un vault con <code>Piano.pdf</code>, <code>Piano.png</code>, <code>piano.PNG</code> e <code>Altro.png</code> (e una nota <code>Piano.md</code>): lavagna → <em>Aggiungi media</em> e <em>Aggiungi nota</em>; disegno → incorporare un&#39;immagine, un disegno, una nota.</td><td>Le voci con la stessa etichetta senza estensione (<code>Piano</code>, anche se differiscono per le maiuscole) mostrano il <strong>percorso completo con l&#39;estensione</strong> (<code>Piano.pdf</code>, <code>Piano.png</code>, <code>piano.PNG</code>); le voci uniche (<code>Altro</code>) restano senza estensione. Scegliendone una si inserisce il file giusto.</td><td></td></tr></tbody></table><h2 id="_2-applicazioni-su-windows-e-linux" tabindex="-1">2. Applicazioni su Windows e Linux <a class="header-anchor" href="#_2-applicazioni-su-windows-e-linux" aria-label="Permalink to &quot;2. Applicazioni su Windows e Linux&quot;">​</a></h2><p>Si eseguono i casi della <a href="./m18-webview-matrice.html">matrice</a>: <strong>sezione 2</strong> (WE1…WE25 e, con <code>CLARAE_WEBVIEW=off</code>, W1…W7) su Windows e <strong>sezione 3</strong> (LE1…LE26 e, con <code>CLARAE_WEBVIEW=off</code>, L1…L3) su Linux, in X11 e in Wayland. Non si ripetono qui. Per un primo giro, in quest&#39;ordine:</p><ol><li>Windows con il runtime: WE1, WE4, WE5, WE6, WE17, WE19.</li><li>Windows senza il runtime (o con <code>CLARAE_WEBVIEW=off</code>): WE2, WE24, W1…W3.</li><li>Linux, X11 e Wayland: LE1, LE2, LE3, LE4, LE8, LE9, LE10, LE19.</li><li>Linux, ripiego e ambienti: LE27 (senza <code>bwrap</code>), LE28 (variabile che disattiva la sandbox), LE29 (Flatpak e Snap), LE30 e LE31 (redirect e iframe), LE32.</li><li>Linux con <code>CLARAE_WEBVIEW=off</code>: LE7, L1…L3.</li></ol><p><strong>Da annotare comunque:</strong> il sistema, la versione del runtime (WebView2 o <code>webkit2gtk-4.1</code>), la sessione (X11 o Wayland, nativo o XWayland), la scala dello schermo e il valore di ogni variabile <code>WEBKIT_*</code> impostata.</p><p><strong>Se la vista si comporta male su un computer</strong> e occorre continuare a lavorare: avviare l&#39;app con <code>CLARAE_WEBVIEW=off</code> (solo Windows e Linux) oppure togliere <code>features.web_viewer</code> dal profilo.</p><h2 id="registro-delle-esecuzioni" tabindex="-1">Registro delle esecuzioni <a class="header-anchor" href="#registro-delle-esecuzioni" aria-label="Permalink to &quot;Registro delle esecuzioni&quot;">​</a></h2><p>Una riga per esecuzione. Un difetto va annotato sotto il caso con il suo livello e, se riguarda ADR-0062 o ADR-0063 (accettati il 2026-11-20), riportato in <a href="./../roadmap.html"><code>docs/roadmap.md</code></a> §13-quindecies.</p><table tabindex="0"><thead><tr><th>Data</th><th>Sistema operativo e versione</th><th>Versione dell&#39;app</th><th>Esecutore</th><th>Casi eseguiti</th><th>Difetti</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>',20)])])}const g=o(t,[["render",n]]);export{u as __pageData,g as default};
